from requests import Session


class Connection(object):
    _SECURED = 'https'
    _PATH = '/xmlapi/invoke'
    _DEFAULT_HEADER = {'Content-Type': 'text/xml_api; charset=ISO-8859-1'}
    _URL = '{protocol}://{ip}:{port}{path}'

    def __init__(self, ip, username, password, port):
        self._ip = ip
        self._username = username
        self._password = password
        self._port = port or 8443
        self._request_prepare()
        self._url = self._URL.format(protocol=self._SECURED,
                                     ip=self._ip,
                                     port=str(port),
                                     path=self._PATH)

    def _request_prepare(self):
        self._session = Session()
        self._auth = (self._username, self._password)
        self._session.verify = False

    def send_request(self, data):
        response = self._session.post(self._url, data=data, headers=self._DEFAULT_HEADER)
        response.raise_for_status()
        return response.text
